package org.icu.sepsis.deterioration;
import java.time.*;import java.util.*;import java.util.stream.Collectors;
import org.icu.sepsis.domain.Domain.*;import org.icu.sepsis.integration.ClinicalDataProvider;import org.icu.sepsis.sepsis.SepsisAssessmentService;import org.springframework.stereotype.Service;
@Service public class DeteriorationService{
 @org.springframework.beans.factory.annotation.Autowired private org.springframework.beans.factory.ObjectProvider<ReviewedLabEvidenceService> labReviews;
 @org.springframework.beans.factory.annotation.Autowired private org.springframework.beans.factory.ObjectProvider<SpecialtyEvidenceService> specialty;
 private final ClinicalDataProvider data;private final SepsisAssessmentService sepsis;
 public DeteriorationService(ClinicalDataProvider data,SepsisAssessmentService sepsis){this.data=data;this.sepsis=sepsis;}
 public Map<String,Object> read(Patient p,Instant now){
  Map<String,Object> review;try{review=sepsis.assess(p,now);}catch(RuntimeException e){review=Map.of("available",false);}
  List<Observation> rows;boolean read=true;try{rows=data.observations(p.id,p.encounterId,now.minus(Duration.ofDays(7)),now);}catch(RuntimeException e){rows=List.of();read=false;}
  List<Map<String,Object>> pending=List.of();String reviewStatus="not_available";
  var verifier=labReviews==null?null:labReviews.getIfAvailable();
  if(verifier!=null)try{var resolved=verifier.resolve(p,rows,now);pending=resolved.evidence;rows=resolved.observations;reviewStatus="available";}catch(RuntimeException e){reviewStatus="unavailable";}
  var result=evaluate(p,now,review,rows,read);var specialist=specialty==null?null:specialty.getIfAvailable();if(specialist!=null)try{var packet=specialist.assess(p,now,rows,(Map<String,Object>)result.get("aki"));result.put("specialty",packet);var organs=(List<Map<String,Object>>)result.get("organs");for(var raw:(List<?>)packet.get("modules")){var module=(Map<?,?>)raw;var icu08=module.get("icu08") instanceof Map?(Map<?,?>)module.get("icu08"):Map.of();boolean candidate="candidate".equals(module.get("status"))||("ards".equals(module.get("key"))&&"candidate".equals(icu08.get("status")));if(candidate){int index=Map.of("aki",2,"ards",0,"dic",3,"liver",4,"delirium",5).get(module.get("key"));organs.get(index).put("status","review_required");organs.get(index).put("detail","ards".equals(module.get("key"))&&"candidate".equals(icu08.get("status"))?"符合 ICU-08 入科24小时路径，需复核临床适用性":module.get("detail"));}}long affected=organs.stream().filter(o->"review_required".equals(o.get("status"))).count();result.put("affectedSystems",affected);result.put("summary",affected>=2?"多系统异常，建议联合复核":affected==1?"单系统异常，需结合临床复核":"专项证据不足，不能排除恶化");}catch(RuntimeException unavailable){result.put("specialtyError","专项临床复核来源不可用，未完成专项评估");}result.put("labEvidence",pending);result.put("labReviewStatus",reviewStatus);return result;
 }
 public static Map<String,Object> evaluate(Patient p,Instant now,Map<String,Object> review,List<Observation> rows,boolean complete){
  String[][] groups={{"respiratory","呼吸","RR","SPO2","PF_RATIO"},{"circulatory","循环","MAP","MAP_IBP","MAP_NIBP","SBP","SBP_IBP","SBP_NIBP","HR","LACTATE"},{"renal","肾脏","CREA","URINE_OUTPUT"},{"coagulation","凝血","PLT"},{"hepatic","肝脏","TBIL"},{"neurologic","神经","GCS"}};
  var organs=new ArrayList<Map<String,Object>>();var findings=(List<Map<String,Object>>)review.getOrDefault("findings",List.of());var evidence=(List<Map<String,Object>>)review.getOrDefault("latestEvidence",List.of());boolean available=Boolean.TRUE.equals(review.get("available"));
  for(var group:groups){var codes=new HashSet<>(Arrays.asList(group).subList(2,group.length));var hits=findings.stream().filter(f->codes.contains(f.get("code"))).collect(Collectors.toList());var present=evidence.stream().filter(f->codes.contains(f.get("code"))).collect(Collectors.toList());var item=new LinkedHashMap<String,Object>();String status=!available||present.isEmpty()?"unknown":!hits.isEmpty()?"review_required":"no_observed_trigger";item.put("key",group[0]);item.put("label",group[1]);item.put("status",status);item.put("evidence",present);item.put("findings",hits);item.put("detail",!available?"来源不可用":!hits.isEmpty()?"现有异常需复核；不等于器官衰竭":present.isEmpty()?"缺少可用观测，当前无法评估":"当前观测未触发异常提示；不能据此排除器官功能障碍");organs.add(item);}
  var scoped=rows.stream().filter(o->Objects.equals(o.patientId,p.id)&&Objects.equals(o.encounterId,p.encounterId)&&Objects.equals(o.department,p.department)).collect(Collectors.toList());var aki=aki(scoped,now,complete);var urine=HourlyUrineAssessment.evaluate(scoped,now,complete);aki.put("urine",urine);aki.put("combined",RenalReview.combine(aki,urine));aki.put("urineStatus",urine.get("status"));aki.put("urineReason",urine.get("detail"));aki.put("stagingStatus","baseline_and_full_staging_unconfirmed");if(!"unknown".equals(urine.get("status")))aki.put("detail",String.valueOf(aki.get("detail")).replace("尿量路径及完整性未知","尿量路径另见独立窗口"));if(aki.get("latest") instanceof Map){var renalEvidence=new ArrayList<Map<String,Object>>((List<Map<String,Object>>)organs.get(2).get("evidence"));if(renalEvidence.stream().noneMatch(e->"CREA".equals(e.get("code"))))renalEvidence.add((Map<String,Object>)aki.get("latest"));organs.get(2).put("evidence",renalEvidence);}var respiratory=OrganContext.respiratory(scoped,now);var neurologic=OrganContext.neurologic(scoped,now);if("candidate".equals(aki.get("status"))||"candidate".equals(urine.get("status"))||Boolean.TRUE.equals(aki.get("historicalCandidate"))){organs.get(2).put("status","review_required");organs.get(2).put("detail","candidate".equals(urine.get("status"))?urine.get("detail"):aki.get("detail"));}
  long affected=organs.stream().filter(o->"review_required".equals(o.get("status"))).count();var out=new LinkedHashMap<String,Object>();out.put("schemaVersion",1);out.put("patientId",p.id);out.put("encounterId",p.encounterId);out.put("asOf",now);out.put("organs",organs);out.put("aki",aki);out.put("respiratory",respiratory);out.put("neurologic",neurologic);out.put("affectedSystems",affected);out.put("sourceReadSucceeded",complete&&available);out.put("complete",null);out.put("summary",affected>=2?"多系统异常，建议联合复核":affected==1?"单系统异常，需结合临床复核":"专项证据不足，不能排除恶化");out.put("clinicalUse","candidate_review_only");return out;
 }
 public static Map<String,Object> aki(List<Observation> rows,Instant now,boolean complete){
  var out=new LinkedHashMap<String,Object>();out.put("ruleVersion","aki-creatinine-nice-ng148-draft-v1");out.put("ruleSource","https://www.nice.org.uk/guidance/ng148/chapter/Recommendations");out.put("urineStatus","unknown");var weight=OrganContext.latest(rows,"WEIGHT",now,Duration.ofDays(7));out.put("weight",weight!=null&&"kg".equals(weight.unit)&&weight.value>0?OrganContext.point(weight):null);out.put("urineReason",weight!=null&&"kg".equals(weight.unit)&&weight.value>0?"已取得体重，仍缺少已核验连续尿量区间及覆盖信息，未作尿量诊断":"体重、尿量区间及完整性未确认，未作尿量诊断");
  var valid=rows.stream().filter(o->"CREA".equals(o.parameterCode)&&o.value!=null&&Double.isFinite(o.value)&&o.value>0&&(o.ingestTime==null||!o.ingestTime.isAfter(now))&&o.eventTime!=null&&!o.eventTime.isAfter(now)&&!o.eventTime.isBefore(now.minus(Duration.ofDays(7)))&&"valid".equals(o.qualityStatus)&&!"context_only".equals(o.clinicalUse)&&!"unconfirmed".equals(o.encounterLinkStatus)&&("μmol/L".equals(o.unit)||"µmol/L".equals(o.unit))).sorted(Comparator.comparing(o->o.eventTime)).collect(Collectors.toList());
  out.put("validMeasurements",valid.size());out.put("excludedMeasurements",rows.stream().filter(o->"CREA".equals(o.parameterCode)).count()-valid.size());
  if(!complete)return unknown(out,"肌酐来源读取失败");if(valid.isEmpty())return unknown(out,"无已核验的本次住院肌酐；检验报告归属或单位待核对");
  var times=new HashMap<Instant,Double>();for(var o:valid){var prior=times.putIfAbsent(o.eventTime,o.value);if(prior!=null&&Double.compare(prior,o.value)!=0)return unknown(out,"同刻肌酐冲突，未挑选数值计算");}
  var unique=new ArrayList<Observation>();var seen=new HashSet<Instant>();for(var o:valid)if(seen.add(o.eventTime))unique.add(o);valid=unique;
  out.put("series",valid.stream().map(DeteriorationService::point).collect(Collectors.toList()));
  var peak=valid.stream().max(Comparator.comparingDouble(o->o.value)).orElseThrow();out.put("peak",point(peak));
  var triggers=new ArrayList<Map<String,Object>>();
  for(int i=1;i<valid.size();i++){var current=valid.get(i);Observation low=null,low48=null;for(int j=0;j<i;j++){var earlier=valid.get(j);if(earlier.eventTime.isBefore(current.eventTime.minus(Duration.ofDays(7))))continue;if(low==null||earlier.value<low.value)low=earlier;if(!earlier.eventTime.isBefore(current.eventTime.minus(Duration.ofHours(48)))&&(low48==null||earlier.value<low48.value))low48=earlier;}
   if(low!=null&&(current.value/low.value>=1.5||(low48!=null&&current.value-low48.value>=26))){var t=new LinkedHashMap<String,Object>();t.put("time",current.eventTime);t.put("value",current.value);t.put("unit",current.unit);t.put("comparison",point(low));t.put("comparison48h",low48==null?null:point(low48));triggers.add(t);}}
  out.put("candidateEvents",triggers);out.put("historicalCandidate",!triggers.isEmpty());out.put("stagingStatus","baseline_and_urine_unconfirmed");
  var latest=valid.get(valid.size()-1);out.put("latest",point(latest));if(latest.eventTime.isBefore(now.minus(Duration.ofHours(24))))return unknown(out,"末次肌酐超过24h，仅供历史复核");
  var prior=valid.stream().filter(o->o.eventTime.isBefore(latest.eventTime)).collect(Collectors.toList());if(prior.isEmpty())return unknown(out,"缺少更早肌酐，不能用单次偏高判断AKI");
  Observation baseline=null;for(var o:prior)if(baseline==null||o.value<baseline.value)baseline=o;
  var prior48=prior.stream().filter(o->!o.eventTime.isBefore(latest.eventTime.minus(Duration.ofHours(48)))).min(Comparator.comparingDouble(o->o.value));
  boolean absolute=prior48.isPresent()&&latest.value-prior48.get().value>=26;boolean relative=latest.value/baseline.value>=1.5;
  out.put("comparison48h",prior48.isPresent()?point(prior48.get()):null);out.put("comparison",point(baseline));out.put("comparisonBasis","近7天已核验记录最低值，非已确认稳定基线");out.put("ratio",latest.value/baseline.value);out.put("rise48h",prior48.isPresent()?latest.value-prior48.get().value:null);out.put("status",absolute||relative?"candidate":"not_triggered");out.put("courseStatus",absolute||relative?"current_candidate":!triggers.isEmpty()?"prior_candidate":"no_observed_trigger");out.put("detail",absolute||relative?"肌酐变化达到NG148候选复核条件，需核对基线、CKD及临床背景；非完整AKI诊断或分期":"末次肌酐比较未触发候选条件；需结合此前候选时序，尿量路径及完整性未知，不能排除AKI或确认恢复");return out;
 }
 private static Map<String,Object> unknown(Map<String,Object> out,String detail){out.put("status","unknown");out.put("detail",detail);return out;}
 private static Map<String,Object> point(Observation o){var out=new LinkedHashMap<String,Object>();out.put("code",o.parameterCode);out.put("value",o.value);out.put("unit",o.unit);out.put("time",o.eventTime);out.put("source",o.sourceSystem);out.put("sourceRecordId",o.sourceRecordId);out.put("timeBasis",o.timeBasis);out.put("encounterLinkStatus",o.encounterLinkStatus);return out;}
}
